import path from 'path';
import { PactV3, MatchersV3 } from '@pact-foundation/pact';
import axios from 'axios';

const { like, eachLike } = MatchersV3;

// ─── Mock server Pact ────────────────────────────────────────────────────────
// Consumer = MFE  |  Provider = BFF

const provider = new PactV3({
  consumer: 'martech-theloophub-mfe',
  provider: 'martech-oneway-reports-bff',
  dir: path.resolve(process.cwd(), 'pacts'),
  logLevel: 'warn',
});

// ─── Tipos espelhados do BFF ──────────────────────────────────────────────────

interface BrandImageResponse {
  url: string;
  matched: string[];
  image_variants: { square: string; table: string };
}

interface CountryImageResponse {
  url: string;
  matched: string[];
}

// ─── Helper: chama o BFF via axios apontando para o mock server ───────────────

function bffClient(mockUrl: string) {
  return {
    getBrand: (params: Record<string, string>) =>
      axios.get<BrandImageResponse>(`${mockUrl}/images/brand`, { params }),
    getCountry: (params: Record<string, string>) =>
      axios.get<CountryImageResponse>(`${mockUrl}/images/country`, { params }),
  };
}

// ─── GET /images/brand ────────────────────────────────────────────────────────

describe('MFE → BFF | GET /images/brand', () => {

  it('retorna url, matched e image_variants para marca conhecida (format=square)', async () => {
    await provider
      .given('a brand image exists for "corona"')
      .uponReceiving('GET /images/brand?name=corona&format=square')
      .withRequest({
        method: 'GET',
        path: '/images/brand',
        query: { name: 'corona', format: 'square' },
      })
      .willRespondWith({
        status: 200,
        headers: { 'Content-Type': 'application/json' },
        body: {
          url: like('https://cdn.example.com/brands/corona/square.png'),
          matched: eachLike('corona'),
          image_variants: {
            square: like('https://cdn.example.com/brands/corona/square.png'),
            table: like('https://cdn.example.com/brands/corona/table.png'),
          },
        },
      })
      .executeTest(async (mockServer) => {
        const { data, status } = await bffClient(mockServer.url).getBrand({
          name: 'corona',
          format: 'square',
        });

        expect(status).toBe(200);
        expect(typeof data.url).toBe('string');
        expect(data.url).toMatch(/^https?:\/\//);
        expect(Array.isArray(data.matched)).toBe(true);
        expect(data.matched.length).toBeGreaterThan(0);
        expect(data.image_variants).toHaveProperty('square');
        expect(data.image_variants).toHaveProperty('table');
      });
  });

  it('retorna url, matched e image_variants para marca com format=table', async () => {
    await provider
      .given('a brand image exists for "corona"')
      .uponReceiving('GET /images/brand?name=corona&format=table')
      .withRequest({
        method: 'GET',
        path: '/images/brand',
        query: { name: 'corona', format: 'table' },
      })
      .willRespondWith({
        status: 200,
        headers: { 'Content-Type': 'application/json' },
        body: {
          url: like('https://cdn.example.com/brands/corona/table.png'),
          matched: eachLike('corona'),
          image_variants: {
            square: like('https://cdn.example.com/brands/corona/square.png'),
            table: like('https://cdn.example.com/brands/corona/table.png'),
          },
        },
      })
      .executeTest(async (mockServer) => {
        const { data } = await bffClient(mockServer.url).getBrand({
          name: 'corona',
          format: 'table',
        });
        expect(data.url).toMatch(/^https?:\/\//);
        expect(data.image_variants).toHaveProperty('square');
      });
  });

  it('retorna URL da brand com underscore no slug (sem hífen)', async () => {
    await provider
      .given('a brand image exists for "michelob ultra"')
      .uponReceiving('GET /images/brand?name=michelob ultra&format=table')
      .withRequest({
        method: 'GET',
        path: '/images/brand',
        query: { name: 'michelob ultra', format: 'table' },
      })
      .willRespondWith({
        status: 200,
        headers: { 'Content-Type': 'application/json' },
        body: {
          url: like('https://assets-martech-uat.mybees-platform.dev/brands/michelob_ultra/table.png'),

          matched: eachLike('michelob ultra'),
          image_variants: {
            square: like('https://assets-martech-uat.mybees-platform.dev/brands/michelob_ultra/square.png'),
            table: like('https://assets-martech-uat.mybees-platform.dev/brands/michelob_ultra/table.png'),
          },
        },
      })
      .executeTest(async (mockServer) => {
        const { data } = await bffClient(mockServer.url).getBrand({
          name: 'michelob ultra',
          format: 'table',
        });

        expect(data.url).toContain('/brands/michelob_ultra/');
        expect(data.url).not.toContain('/brands/michelob-ultra/');
        expect(data.image_variants.table).toContain('/brands/michelob_ultra/');
        expect(data.image_variants.square).toContain('/brands/michelob_ultra/');
      });
  });

  it('retorna placeholder quando marca não existe (matched=[])', async () => {
    await provider
      .given('no brand image exists for "unknown-brand-xyz"')
      .uponReceiving('GET /images/brand?name=unknown-brand-xyz')
      .withRequest({
        method: 'GET',
        path: '/images/brand',
        query: { name: 'unknown-brand-xyz', format: 'square' },
      })
      .willRespondWith({
        status: 200,
        headers: { 'Content-Type': 'application/json' },
        body: {
          url: like('https://cdn.example.com/brands/placeholder/square.png'),
          matched: [],
          image_variants: {},
        },
      })
      .executeTest(async (mockServer) => {
        const { data } = await bffClient(mockServer.url).getBrand({
          name: 'unknown-brand-xyz',
          format: 'square',
        });
        expect(data.matched).toHaveLength(0);
        expect(data.url).toMatch(/^https?:\/\//);
      });
  });

  /**
   * Documenta o parâmetro brand_family (snake_case).
   * ATENÇÃO: o MFE atualmente envia brandFamily (camelCase) — isso NÃO chega ao BFF.
   * Este teste usa o nome correto esperado pelo DTO do BFF.
   */
  it('aceita brand_family como parâmetro opcional', async () => {
    await provider
      .given('a brand image exists for family "all"')
      .uponReceiving('GET /images/brand com brand_family=all')
      .withRequest({
        method: 'GET',
        path: '/images/brand',
        query: { name: 'all', format: 'square', brand_family: 'stella_artois' },
      })
      .willRespondWith({
        status: 200,
        headers: { 'Content-Type': 'application/json' },
        body: {
          url: like('https://cdn.example.com/brands/premium/square.png'),
          matched: eachLike('stella artois'),
          image_variants: {
            square: like('https://cdn.example.com/brands/premium/square.png'),
            table: like('https://cdn.example.com/brands/premium/table.png'),
          },
        },
      })
      .executeTest(async (mockServer) => {
        const { data } = await bffClient(mockServer.url).getBrand({
          name: 'all',
          format: 'square',
          brand_family: 'stella_artois',
        });
        expect(data.url).toMatch(/^https?:\/\//);
      });
  });
});

// ─── GET /images/country ──────────────────────────────────────────────────────

